/* Signature Unified Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Person-name words": "The published language maps lineage words that serve as personal names: compact agglutinative compounds from the 23-phon", "Kin-name compounds": "Family and kin terms compound into names, marking lineage directly in the name word.", "Virtue-name words": "Abstract virtue roots become personal names through the language's regular agglutination.", "Nature-name words": "Sun, moon, river and mountain roots form name words in the documented word-stock.", "Craft-name words": "Words for making, building and singing compound into occupational name words.", "Star-name words": "Celestial roots form names, reflecting the language's SOV cosmic vocabulary.", "Lineage markers": "Surnames in the system are lineage markers: the 716 lineage-mapped words include family-line roots.", "House compounds": "House and hall roots compound into family-name words.", "Guild markers": "Craft-guild roots serve as inherited name markers.", "Oath markers": "Oath and bond roots form family names of allegiance."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Person-name words';
console.log(lookup(q));

